import java.util.*;
import org.objectweb.asm.tree.*;
import static org.objectweb.asm.Opcodes.*;

/** Independent inverse of the three WORLD magic bridges and full native publisher. */
final class VerifyWorldMagic {
 static final String P="local/lito381/server/",C=P+"ClientSession",H=P+"CombatWorldMagic",W=P+"ClassicWorldMonsterPopulation",A=H+"$Attempt",SPELL="L"+P+"BattleSpellCatalog$AttackSpell;",U="L"+W+"$PoisonUpdate;",S="L"+P+"CombatPoisonLifecycle$Scope;";
 static void need(boolean yes,String why){if(!yes)throw new AssertionError("WORLD magic "+why);}
 static AbstractInsnNode before(AbstractInsnNode n){return VerifyCombatPreservation.prior(n);}static AbstractInsnNode after(AbstractInsnNode n){return VerifyCombatPreservation.following(n);}
 static int local(MethodNode m,String name){return VerifyLineSpells.slot(m,name);}
 static void loads(MethodNode m,AbstractInsnNode call,int[] opcodes,int[] slots){var cursor=before(call);for(int i=slots.length-1;i>=0;i--){need(cursor instanceof VarInsnNode v&&v.getOpcode()==opcodes[i]&&v.var==slots[i],"same original value local "+i);var previous=before(cursor);m.instructions.remove(cursor);cursor=previous;}}
 static ClassNode normalize(ClassNode source){
  if(!source.name.equals(C))return source;var c=new ClassNode();source.accept(c);var methods=c.methods.stream().filter(m->m.name.equals("sourceWorldMagicPublished")).toList();need(methods.size()==1,"one declared native publisher clone");var clone=methods.get(0);need(clone.access==ACC_PRIVATE&&clone.desc.equals("(IL"+W+"$Hit;"+U+S+")V"),"exact publisher signature");var counts=new TreeMap<String,Integer>();for(var n:clone.instructions)if(n instanceof MethodInsnNode x&&x.owner.equals(P+"CombatWorldCommit"))counts.merge(x.name,1,Integer::sum);need(counts.equals(new TreeMap<>(Map.of("boss",1,"members",1,"name",1,"rewards",1,"same",1,"schedule",1,"send",2))),"exact native publisher bridge counts");
  var expected=c.methods.stream().filter(m->m.name.equals("publishClassicWorldSpellMonsterDamage")&&m.desc.equals("(IL"+W+"$Hit;)V")).findFirst().orElseThrow();var restored=VerifyWorldCommit.restorePublisher(clone,3,4);var left=Arrays.stream(expected.instructions.toArray()).filter(n->n.getOpcode()>=0).toList();var right=Arrays.stream(restored.instructions.toArray()).filter(n->n.getOpcode()>=0).toList();need(left.size()==right.size(),"whole native publisher instruction count");var mapping=new HashMap<Integer,Integer>(Map.of(0,0,1,1,2,2));var used=new HashSet<Integer>(mapping.values());
  for(int i=0;i<left.size();i++)if(left.get(i) instanceof VarInsnNode old&&right.get(i) instanceof VarInsnNode now){need(old.getOpcode()==now.getOpcode(),"publisher local opcode");if(!mapping.containsKey(old.var)){need(used.add(now.var),"distinct publisher local");mapping.put(old.var,now.var);}need(mapping.get(old.var)==now.var,"publisher local remains same value");now.var=old.var;}
  restored.name=expected.name;restored.desc=expected.desc;restored.signature=expected.signature;need(VerifyCombatPreservation.semantic(expected).equals(VerifyCombatPreservation.semantic(restored)),"all remaining publisher loops, packets, death/rewards/schedule opcodes");c.methods.remove(clone);
  var bridges=new TreeMap<String,Integer>();for(var m:c.methods){int attempt=-1;for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode x&&x.owner.equals(H)){
   need(m.name.equals("useClassicWorldAttackSpell")&&m.desc.equals("(L"+P+"Protocol$AttackSpellRequest;"+SPELL+")V"),"one original WORLD request ingress");bridges.merge(x.name,1,Integer::sum);
   if(x.name.equals("critical")){need(x.desc.equals("("+SPELL+"IZL"+C+";L"+P+"CombatMagicDamage$Attempt;ZIL"+C+";L"+W+"$Snapshot;)I"),"typed scalar bridge signature");loads(m,x,new int[]{ILOAD,ILOAD,ALOAD,ALOAD},new int[]{local(m,"validOrdinaryMonster"),local(m,"targetMagicResistance"),0,local(m,"monsterTarget")});m.instructions.set(x,new MethodInsnNode(INVOKESTATIC,P+"CombatCompanionDamage","beforeCritical","("+SPELL+"IZL"+C+";L"+P+"CombatMagicDamage$Attempt;)I",false));}
   else if(x.name.equals("prepare")){need(x.desc.equals("(L"+C+";ZL"+W+"$Snapshot;L"+P+"BattleSpellCatalog$ThunderGrabSpell;L"+P+"SourceNpcPhysicalStats;I)L"+A+";"),"typed action preparation");var stored=after(x);need(stored instanceof VarInsnNode v&&v.getOpcode()==ASTORE&&after(stored) instanceof MethodInsnNode pub&&pub.owner.equals(C)&&pub.name.equals("publishClassicWorldAttackSpellPacket"),"immediately before native resolved action publication");attempt=((VarInsnNode)stored).var;loads(m,x,new int[]{ALOAD,ILOAD,ALOAD,ALOAD,ALOAD,ILOAD},new int[]{0,local(m,"validOrdinaryMonster"),local(m,"monsterTarget"),local(m,"thunderGrab"),local(m,"npcStats"),local(m,"casterLevel")});m.instructions.remove(stored);m.instructions.remove(x);}
   else if(x.name.equals("enqueue")){need(attempt>=0&&x.desc.equals("(L"+A+";L"+C+";I"+SPELL+"L"+P+"BattleEraseMagicStatus$Lease;)Z"),"typed deferred entry");var jump=after(x);need(jump instanceof JumpInsnNode j&&j.getOpcode()==IFNE,"handled branch preserves native fallback");var hp=c.methods.stream().filter(method->method==m).flatMap(method->Arrays.stream(method.instructions.toArray())).filter(q->q instanceof MethodInsnNode call&&call.owner.equals(P+"GameHub")&&call.name.equals("damageClassicWorldMonster")).findFirst().orElseThrow();int hit=((VarInsnNode)after(hp)).var;var scope=m.localVariables.stream().filter(v->v.index==hit&&v.name.equals("transition")&&v.desc.equals("L"+W+"$Hit;")).findFirst().orElseThrow();need(((JumpInsnNode)jump).label==scope.end,"skip exactly the native ordinary-monster HP/effect branch");var retained=after(jump);need(retained instanceof VarInsnNode v&&v.getOpcode()==ILOAD&&v.var==local(m,"damage")&&after(retained).getOpcode()==IFGT,"native positive/null HP guard retained in fallback");loads(m,x,new int[]{ALOAD,ALOAD,ILOAD,ALOAD,ALOAD},new int[]{attempt,0,local(m,"damage"),local(m,"spell"),local(m,"eraseMagicLease")});m.instructions.remove(jump);m.instructions.remove(x);}
   else throw new AssertionError("unknown WORLD magic bridge "+x.name);
  }
  if(attempt>=0){int initializers=0;for(var n:m.instructions.toArray())if(n instanceof VarInsnNode v&&v.var==attempt){need(v.getOpcode()==ASTORE&&before(v).getOpcode()==ACONST_NULL,"only one method-local null initializer remains");m.instructions.remove(before(v));m.instructions.remove(v);initializers++;}need(initializers==1,"one method-local attempt initializer");}}
  need(bridges.equals(new TreeMap<>(Map.of("critical",1,"prepare",1,"enqueue",1))),"three exact producer bridges");return c;
 }
}
